  matches(selector){return selector.split(',').some(part=>{part=part.trim();if(!part)return false;const attrs=[...part.matchAll(/\[([^\]=]+)(?:="([^"]*)")?\]/g)];if(attrs.some(([,key,value])=>!this.hasAttribute(key)||(value!==undefined&&this.getAttribute(key)!==value)))return false;const plain=part.replace(/\[[^\]]*\]/g,''),tag=plain.match(/^[a-z][\w-]*/i)?.[0],id=plain.match(/#([\w-]+)/)?.[1],classes=[...plain.matchAll(/\.([\w-]+)/g)].map(match=>match[1]);return(!tag||this.tagName===tag.toLowerCase())&&(!id||this.id===id)&&classes.every(name=>this.classList.contains(name))})}
