function serialize(node){if(node.tagName==='#text')return projectNoteEscape(node._text);const attributes={...node.attributes,...Object.fromEntries(Object.entries(node.dataset).map(([key,value])=>[dataName(key),value]))};return '<'+node.tagName+Object.entries(attributes).map(([key,value])=>' '+key+'="'+projectNoteEscape(value)+'"').join('')+'>'+node.innerHTML+'</'+node.tagName+'>'}
function parseHtml(html,parent){const stack=[parent];const voidTags=new Set(['input','br','hr','img','meta','link']);for(const match of html.matchAll(/<!--[\s\S]*?-->|<\/[a-z][^>]*>|<[a-z][^>]*>|[^<]+/gi)){const token=match[0];if(token.startsWith('<!--'))continue;if(token.startsWith('</')){const tag=token.slice(2,-1).trim().toLowerCase();while(stack.length>1){if(stack.pop().tagName===tag)break}continue}if(token[0]==='<'){const [,tag,attributes]=token.match(/^<([a-z][\w-]*)([\s\S]*?)\/?\s*>$/i),node=new FixtureNode(tag,parent.document);for(const attr of attributes.matchAll(/([\w:-]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g))node.setAttribute(attr[1],decode(attr[2]??attr[3]??attr[4]??''));stack.at(-1).append(node);if(!voidTags.has(node.tagName))stack.push(node)}else{const node=new FixtureNode('#text',parent.document);node._text=decode(token);stack.at(-1).append(node)}}}
function fixtureDocument(){const document={listeners:{},activeElement:null,createElement(tag){return new FixtureNode(tag,this)},addEventListener(type,fn,options={}){(this.listeners[type]||=[]).push({fn,capture:options.capture===true})},querySelector(selector){return this.body.querySelector(selector)},querySelectorAll(selector){return this.body.querySelectorAll(selector)},getElementById(id){return this.querySelector('#'+id)},dispatch(type,target,extra={}){const event={type,target,defaultPrevented:false,preventDefault(){this.defaultPrevented=true},stopPropagation(){this.stopped=true},...extra},ancestors=[];for(let node=target;node;node=node.parentNode)ancestors.push(node);const invoke=(owner,capture)=>{event.currentTarget=owner;for(const listener of owner.listeners?.[type]||[])if(listener.capture===capture)listener.fn(event);if(!capture&&typeof owner['on'+type]==='function')owner['on'+type](event)};invoke(this,true);for(const node of [...ancestors].reverse())invoke(node,true);for(const node of ancestors){invoke(node,false);if(event.stopped)break}if(!event.stopped)invoke(this,false);return event}};document.body=new FixtureNode('body',document);return document}
function item(overrides={}){return{id:'synthetic-note',kind:'note',text:'Synthetic project update',completed:false,revision:1,createdBy:'Synthetic user',createdAt:'2026-10-04T18:00:00Z',updatedBy:'Synthetic user',updatedAt:'2026-10-04T18:00:00Z',history:[{action:'created',by:'Synthetic user',at:'2026-10-04T18:00:00Z',after:{text:'Synthetic project update',completed:false}}],...overrides}}
function sharedProjectSections(id){return '<div class="detail-meta" data-fixture-context>Shared project context '+id+'</div><section class="tm-summary" data-fixture-shared="summary"><h3>Time & material summary</h3><p>Approved amount: $1,250.00</p><input data-fixture-summary value="1250.00"></section><section class="project-ticket-section" data-fixture-shared="tickets"><h3>Tickets & receipts</h3><input id="project-ticket-search" value="Synthetic supplier"><select id="project-ticket-status"><option value="all">All statuses</option><option value="Verified">Verified</option></select><div id="project-ticket-list">Synthetic verified receipt</div></section><section class="panel" data-fixture-shared="rates"><h3>Rate for future office approvals</h3><label>Default labor rate<input id="pdl-default-rate" type="number" value="72.50"></label><label>Reason<textarea id="pdl-default-rate-reason"></textarea></label><div><button data-pdl-default-rate="'+id+'">Save future rate</button></div></section><section class="panel" data-fixture-other>Unrelated project information<section class="tm-summary" data-fixture-nested="summary">Nested summary context</section><section class="project-ticket-section" data-fixture-nested="tickets">Nested ticket context</section><section class="project-notes-shared-rates" data-fixture-nested="rates">Nested rate context</section><input data-fixture-other-input value="Keep other input"></section>'}
// This is a selector contract, not simulated browser layout. Read the real
// focus rule, then use its direct-child selectors against fixture membership.
function notesFocusRules(){return [...fs.readFileSync(path.join(__dirname,'project-notes-ui.css'),'utf8').replace(/\/\*[\s\S]*?\*\//g,'').matchAll(/([^{}]+)\{([^{}]*)\}/g)].filter(([,selectors])=>selectors.includes('project-notes-active'))}
function notesFocusHides(node){return notesFocusRules().some(([,selectors,body])=>/\bdisplay\s*:\s*none\b/.test(body)&&selectors.split(',').some(selector=>{const parts=selector.trim().split(/\s*>\s*/);assert.equal(parts.length,2,'Notes focus hiding must use a direct-child selector');return node.matches(parts[1])&&Boolean(node.parentNode?.matches(parts[0]))}))}
function assertNotesFocus(h,selected){const content=h.query('#project-detail-content');assert.equal(content.classList.contains('project-notes-active'),selected);for(const node of h.all('[data-fixture-shared]')){assert.equal(node.isConnected,true);assert.equal(notesFocusHides(node),selected,node.dataset.fixtureShared+' focus visibility');assert.equal(node.hidden,false,'Focus is CSS-only, not a hidden-attribute rewrite')}for(const node of h.all('[data-fixture-context],[data-fixture-other],[data-fixture-nested],.project-detail-tabs,.project-notes-pane'))assert.equal(notesFocusHides(node),false,'Unrelated context, tabs and Notes stay outside the shared-section hiding rule')}
