function assertReadOnlyNotes(h){assert.ok(h.calls.every(call=>call.method==='GET'&&/^\/api\/projects\/\d+\/notes-todos$/.test(call.route)),'Tab/editor navigation must neither write financial records nor mutate notes')}
function harness(options={}){
  const document=fixtureDocument(),calls=[],opens=[],windowListeners={},queues={GET:[],POST:[],PATCH:[]};let uuid=0;
  document.body.innerHTML='<dialog id="project-detail-modal"><h2 id="detail-project-name"></h2><div id="project-detail-content"></div></dialog><button id="logout-button"></button><button id="profile-logout-button"></button><button id="subscription-lock-logout"></button>';
  const context={console,document,Date,JSON,AbortController,crypto:{randomUUID:()=>`synthetic-request-${++uuid}`},currentUser:{id:1,role:'owner',memberId:1,projectIds:[1,2],permissions:{}},currentRole:'office',company:{id:'tenant-a'},tenant:'tenant-a',page:'projects',signedInCompanyId:()=>context.tenant,$:selector=>document.querySelector(selector),$$:selector=>document.querySelectorAll(selector),renderEverything(){context.renderCount=(context.renderCount||0)+1},loadRole:async role=>{context.loadedRole=role;return 'role-result'},showPage(page){context.page=page;return 'page-result'},api:async(route,apiOptions)=>{const method=apiOptions?.method||'GET',call={route,options:apiOptions,method,payload:apiOptions?.body?JSON.parse(apiOptions.body):undefined};calls.push(call);if(queues[method]?.length){const response=queues[method].shift();if(response instanceof Error)throw response;return await response}if(method==='GET')return{items:clone(options.items||[])};return item({id:route.split('/').length>5?decodeURIComponent(route.split('/').at(-1)):'created-'+calls.length,...call.payload,history:[]})},addEventListener(type,fn){(windowListeners[type]||=[]).push(fn)}};
  context.window=context;
  context.openProject=async(id,view)=>{opens.push({id,view});if(options.predecessor)await options.predecessor(id,view);if(view&&!view.current())return;renderBase(id);return 'project-result'};
  function renderBase(id){context.$('#detail-project-name').textContent='Synthetic project '+id;context.$('#project-detail-content').innerHTML='<div class="project-detail-tabs"><button class="active" data-project-detail-tab="estimate">Estimate</button><button data-project-detail-tab="dailies">Dailies</button>'+(options.sharedSections?['photos','plans','changes'].map(key=>'<button data-project-detail-tab="'+key+'">'+key+'</button>').join(''):'')+'</div><section class="project-detail-pane active" data-project-detail-pane="estimate">Original project detail</section><section class="project-detail-pane" data-project-detail-pane="dailies">Original daily detail</section>'+(options.sharedSections?['photos','plans','changes'].map(key=>'<section class="project-detail-pane" data-project-detail-pane="'+key+'">Original '+key+' detail</section>').join('')+sharedProjectSections(id):'');context.$('#project-detail-modal').showModal()}
  vm.createContext(context);if(options.beforeModule)options.beforeModule(context);vm.runInContext(source,context,{filename:'project-notes-ui.js'});
  return{context,document,calls,opens,renderBase,query:selector=>document.querySelector(selector),all:selector=>document.querySelectorAll(selector),respond(method,value){queues[method].push(value)},defer(method){const request=deferred();queues[method].push(request.promise);return request},async open(id=1){const result=await context.openProject(id);await flush();return result},click(selector){const node=document.querySelector(selector);assert.ok(node,'Missing synthetic control '+selector);node.click();return node},keydown(selector,key,extra={}){const node=document.querySelector(selector);assert.ok(node,'Missing synthetic key target '+selector);return document.dispatch('keydown',node,{key,...extra})},fireWindow(type,extra={}){for(const fn of windowListeners[type]||[])fn({type,...extra})}};
}

test('effective notes permissions gate create, edit and completion independently',async()=>{
  const h=harness({items:[item({kind:'todo'})]});h.respond('GET',{items:[item({kind:'todo'})],permissions:{view:true,create:false,edit:false,complete:true}});await h.open();
  assert.equal(h.query('[data-note-new="note"]').disabled,true);assert.equal(h.query('[data-note-edit]'),null);assert.ok(h.query('[data-note-toggle]'));const before=h.calls.length;h.click('[data-note-new="note"]');assert.equal(h.calls.length,before);
  h.respond('GET',{items:[item({kind:'todo'})],permissions:{view:true,create:true,edit:true,complete:false}});h.click('[data-notes-refresh]');await flush();assert.equal(h.query('[data-note-toggle]'),null);assert.equal(h.query('[data-note-new="note"]').disabled,false);assert.ok(h.query('[data-note-edit]'));
});
test('revoked viewing clears delivered items and editor on reload',async()=>{
  const h=harness({items:[item()]});await h.open();h.click('[data-note-edit]');h.query('[data-notes-text]').value='Local draft';h.respond('GET',Object.assign(new Error('Notes viewing disabled'),{status:403}));h.click('[data-notes-refresh]');await flush();assert.equal(h.all('[data-note-card]').length,0);assert.equal(h.query('[data-notes-editor]').hidden,true);assert.equal(h.query('[data-notes-text]').value,'');assert.equal(h.query('[data-note-new="note"]').disabled,true);
});
test('plain-text render escapes every note and history surface without mutating input',()=>{
  const attack='<img src=x onerror="attack()"> & <script>bad()</script>\'"',record=item({id:attack,text:attack,createdBy:attack,updatedBy:attack,revision:2,history:[{action:attack,by:attack,at:attack,before:{text:attack+' before'},after:{text:attack+' after',completed:true}}]}),before=clone(record),markup=projectNoteCard(record),document=fixtureDocument();document.body.innerHTML=markup;
  assert.equal(projectNoteEscape(null),'');assert.equal(projectNoteEscape(0),'0');assert.equal(projectNoteEscape('&<>"\''),'&amp;&lt;&gt;&quot;&#39;');assert.equal(projectNoteTime('not-a-date'),'Unknown time');assert.deepEqual(record,before);
  assert.ok(!markup.includes(attack));assert.ok(markup.includes('&lt;img'));assert.match(markup,/Previous text/);assert.equal(document.querySelectorAll('img,script').length,0);assert.equal(document.querySelectorAll('[onerror]').length,0);assert.equal(document.querySelector('[data-note-edit]').dataset.noteEdit,attack);assert.ok(document.body.textContent.includes(attack+' before'));assert.ok(document.body.textContent.includes(attack+' after'));
  assert.equal(projectNoteCard(item({history:undefined})).includes('History (0)'),true);
});
test('list distinguishes notes, open and completed to-dos and reverses only displayed history',()=>{
  const record=item({kind:'todo',history:[{action:'first-change',by:'a',at:'bad',after:{text:'old',completed:false}},{action:'last-change',by:'b',at:'bad',after:{text:'new',completed:true}}]}),markup=projectNotesList([record,item({id:'done',kind:'todo',completed:true}),item({id:'note'})]);
  assert.match(markup,/Open to-dos <span>1<\/span>/);assert.match(markup,/Completed to-dos \(1\)/);assert.match(markup,/Notes <span>1<\/span>/);assert.match(markup,/Mark complete/);assert.match(markup,/Reopen/);assert.ok(markup.indexOf('last-change')<markup.indexOf('first-change'));assert.equal(record.history[0].action,'first-change');
  assert.match(projectNotesList([]),/No open to-dos/);assert.match(projectNotesList([]),/No notes yet/);assert.match(projectNotesList([]),/reopen them anytime/);
});
test('loading disables new/edit/save and repeated reloads; failure exposes retry; empty load recovers',async()=>{
  const h=harness(),request=h.defer('GET');assert.equal(await h.open(),'project-result');
  assert.match(h.query('[data-notes-message]').textContent,/Loading/);assert.equal(h.query('[data-notes-message]').hidden,false);for(const button of h.all('.project-notes-pane button'))assert.equal(button.disabled,true);assert.equal(h.query('[data-notes-text]').disabled,true);
  h.click('[data-notes-refresh]');h.click('[data-note-new="note"]');assert.equal(h.calls.length,1);assert.equal(h.query('[data-notes-editor]').hidden,true);
  request.reject(new Error('Synthetic unavailable'));await flush();assert.equal(h.query('[data-notes-message]').getAttribute('role'),'alert');assert.match(h.query('[data-notes-message]').textContent,/Synthetic unavailable.*Reload/);assert.equal(h.query('[data-note-new="note"]').disabled,true);assert.equal(h.query('[data-notes-save]').disabled,true);assert.equal(h.query('[data-notes-refresh]').disabled,false);
  h.click('[data-notes-refresh]');await flush();assert.equal(h.calls.length,2);assert.match(h.query('[data-notes-list]').textContent,/No notes yet/);assert.equal(h.query('[data-note-new="note"]').disabled,false);assert.equal(h.query('[data-notes-message]').hidden,true);
});
