  const h=harness();await h.open();h.click('[data-note-new="todo"]');h.query('[data-notes-text]').value='Retry this synthetic task';const request=h.defer('POST');h.click('[data-notes-save]');h.click('[data-notes-save]');h.keydown('[data-notes-text]','Enter',{ctrlKey:true});await flush();assert.equal(h.calls.filter(call=>call.method==='POST').length,1);assert.equal(h.query('[data-notes-cancel]').disabled,true);
