  h.click('[data-notes-save]');await flush();const calls=h.calls.filter(call=>call.method==='POST');assert.equal(calls.length,2);assert.deepEqual(calls[1].payload,calls[0].payload);assert.equal(h.query('[data-project-detail-tab="notes"]').textContent,'Notes & To-dos (1)');
