const invalidations=[
  ['tenant header',h=>{h.context.tenant='tenant-b';h.context.renderEverything()}],
  ['company object',h=>{h.context.company.id='tenant-b';h.context.renderEverything()}],
  ['signed-in user',h=>{h.context.currentUser.id=2;h.context.renderEverything()}],
  ['account role',h=>{h.context.currentUser.role='guest';h.context.renderEverything()}],
  ['member identity',h=>{h.context.currentUser.memberId=2;h.context.renderEverything()}],
  ['assigned projects',h=>{h.context.currentUser.projectIds=[2];h.context.renderEverything()}],
  ['permissions',h=>{h.context.currentUser.permissions={viewPricing:false};h.context.renderEverything()}],
  ['view role',h=>{h.context.currentRole='field';h.context.renderEverything()}],
  ['role loader',h=>h.context.loadRole('field')],
  ['modal close',h=>h.query('#project-detail-modal').close()],
  ['modal cancel',h=>h.document.dispatch('cancel',h.query('#project-detail-modal'))],
  ['logout',h=>h.click('#logout-button')],
  ['profile logout',h=>h.click('#profile-logout-button')],
  ['subscription logout',h=>h.click('#subscription-lock-logout')],
  ['pagehide',h=>h.fireWindow('pagehide')],
  ['tenant storage',h=>h.fireWindow('storage',{key:'pdl-company-id'})],
  ['role storage',h=>h.fireWindow('storage',{key:'pdl-role'})],
  ['project navigation',h=>h.open(2)],
  ['same-project reopen',h=>h.open(1)],
  ['in-app navigation',h=>h.context.showPage('reports')],
  ['Back/Forward navigation',h=>h.fireWindow('popstate')],
  ['hash navigation',h=>h.fireWindow('hashchange')]
];
for(const [label,invalidate] of invalidations){
  test(`Notes focus class clears after ${label}, restoring shared sections without financial writes`,async()=>{
    const note=item(),beforeNote=clone(note),h=harness({sharedSections:true,items:[note]});await h.open();h.query('#project-ticket-search').value='Unchanged ticket search';h.query('#pdl-default-rate').value='91.25';h.query('#pdl-default-rate-reason').value='Unsubmitted reason';const content=h.query('#project-detail-content'),before=sharedSnapshot(h),oldPane=h.query('.project-notes-pane');h.click('[data-project-detail-tab="notes"]');assertNotesFocus(h,true);h.click('[data-note-new="note"]');h.query('[data-notes-text]').value='Old project draft';await invalidate(h);await flush();assert.equal(h.query('#project-detail-content'),content);assertNotesFocus(h,false);assert.equal(oldPane.isConnected,false);assert.equal(h.document.body.textContent.includes('Old project draft'),false);for(const row of before){assert.equal(row.node.innerHTML,row.markup);assert.equal(row.node.className,row.className);assert.equal(row.node.hidden,row.hidden);for(const control of row.controls){assert.equal(control.control.value,control.value);assert.equal(control.control.disabled,control.disabled)}}if(['project navigation','same-project reopen'].includes(label)){assert.equal(h.query('[data-project-detail-pane="estimate"]').classList.contains('active'),true);assert.equal(h.query('[data-notes-editor]').hidden,true);assert.equal(h.query('[data-notes-text]').value,'')}else assertSharedUnchanged(h,before);assert.deepEqual(note,beforeNote);assertReadOnlyNotes(h);
  });
  test(`stale list after ${label} cannot render old project text`,async()=>{
    const h=harness(),request=h.defer('GET');await h.open();const oldPane=h.query('.project-notes-pane');await invalidate(h);assert.equal(oldPane.isConnected,false,`${label} must immediately clear the old notes pane`);request.resolve({items:[item({text:'STALE LIST SECRET'})]});await flush();assert.ok(!h.document.body.textContent.includes('STALE LIST SECRET'));assert.equal(oldPane.querySelectorAll('[data-note-card]').length,0);if(h.query('.project-notes-pane'))assert.equal(h.query('.project-notes-pane').querySelectorAll('[data-note-card]').length,0);
  });
  for(const outcome of ['success','failure'])test(`stale save ${outcome} after ${label} cannot alter current pane or show old feedback`,async()=>{
    const h=harness();await h.open();h.click('[data-note-new="note"]');h.query('[data-notes-text]').value='OLD DRAFT SECRET';const request=h.defer('POST');h.click('[data-notes-save]');await flush();const oldPane=h.query('.project-notes-pane');await invalidate(h);assert.equal(oldPane.isConnected,false);if(!h.query('.project-notes-pane')&&h.context.currentUser?.role!=='guest')await h.open(2);const newPane=h.query('.project-notes-pane'),before=newPane?.innerHTML;
    if(outcome==='success')request.resolve(item({text:'STALE SAVED SECRET'}));else request.reject(new Error('STALE FAILURE SECRET'));await flush();assert.ok(!h.document.body.textContent.includes('STALE SAVED SECRET'));assert.ok(!h.document.body.textContent.includes('STALE FAILURE SECRET'));assert.ok(!h.document.body.textContent.includes('OLD DRAFT SECRET'));if(newPane)assert.equal(newPane.innerHTML,before,'stale result must not reset controls or feedback in the newer view');
  });
  test(`stale list failure after ${label} cannot show old error or reactivate old controls`,async()=>{
    const h=harness(),request=h.defer('GET');await h.open();const oldPane=h.query('.project-notes-pane'),signal=h.calls.at(-1).options.signal;await invalidate(h);assert.equal(signal.aborted,true,`${label} aborts old request`);request.reject(new Error('STALE LIST ERROR SECRET'));await flush();assert.ok(!h.document.body.textContent.includes('STALE LIST ERROR SECRET'));assert.equal(oldPane.querySelector('[data-note-new="note"]').disabled,true);
  });
  test(`stale completion after ${label} cannot update replacement project rows`,async()=>{
    const original=item({id:'task',kind:'todo'}),h=harness({items:[original]});await h.open();const request=h.defer('PATCH');h.click('[data-note-toggle]');await flush();const signal=h.calls.at(-1).options.signal;await invalidate(h);assert.equal(signal.aborted,true);if(!h.query('.project-notes-pane')&&h.context.currentUser?.role!=='guest')await h.open(2);const pane=h.query('.project-notes-pane'),before=pane?.innerHTML;request.resolve(item({...original,completed:true,revision:2,text:'STALE TO-DO SECRET'}));await flush();assert.ok(!h.document.body.textContent.includes('STALE TO-DO SECRET'));if(pane)assert.equal(pane.innerHTML,before);
  });
}
test('closing and reopening from Notes starts the original view and restores only the reopened project context',async()=>{
  const h=harness({sharedSections:true,items:[item({id:'first-project',text:'First project saved note'})]});await h.open(1);h.click('[data-project-detail-tab="notes"]');h.click('[data-note-edit]');h.query('[data-notes-text]').value='First project unsaved edit';h.query('#project-detail-modal').close();assertNotesFocus(h,false);h.respond('GET',{items:[item({id:'second-project',text:'Second project saved note'})]});await h.open(2);assertNotesFocus(h,false);assert.equal(h.query('[data-project-detail-tab="estimate"]').getAttribute('aria-selected'),'true');assert.equal(h.query('[data-notes-editor]').hidden,true);assert.equal(h.query('[data-notes-text]').value,'');h.click('[data-project-detail-tab="notes"]');assertNotesFocus(h,true);assert.match(h.query('[data-notes-list]').textContent,/Second project saved note/);assert.doesNotMatch(h.query('[data-notes-list]').textContent,/First project/);assert.equal(h.query('[data-pdl-default-rate]').dataset.pdlDefaultRate,'2');assertReadOnlyNotes(h);
});
test('identity guard works even before renderEverything has been called',async()=>{
  const h=harness(),request=h.defer('GET');await h.open();h.context.currentUser.id=2;request.resolve({items:[item({text:'UNRENDERED IDENTITY SECRET'})]});await flush();assert.ok(!h.document.body.textContent.includes('UNRENDERED IDENTITY SECRET'));const count=h.calls.length;h.click('[data-notes-refresh]');assert.equal(h.calls.length,count);h.context.renderEverything();assert.equal(h.query('.project-notes-pane'),null);
});
test('unrelated render/storage events preserve an active notes draft',async()=>{
  const h=harness();await h.open();h.click('[data-note-new="note"]');h.query('[data-notes-text]').value='Still here';const pane=h.query('.project-notes-pane');h.context.renderEverything();h.fireWindow('storage',{key:'unrelated-key'});assert.equal(h.query('.project-notes-pane'),pane);assert.equal(h.query('[data-notes-text]').value,'Still here');assert.equal(h.query('[data-notes-editor]').hidden,false);
});
test('newer opening wins when earlier predecessor resolves last',async()=>{
  const old=deferred(),h=harness({predecessor:id=>id===1?old.promise:undefined}),first=h.context.openProject(1);await flush();await h.open(2);assert.equal(h.query('#detail-project-name').textContent,'Synthetic project 2');old.resolve();await first;await flush();assert.equal(h.query('#detail-project-name').textContent,'Synthetic project 2');assert.equal(h.all('[data-project-detail-tab="notes"]').length,1);assert.equal(h.calls.filter(call=>call.route.includes('/1/')).length,0);assert.equal(h.opens[0].view.current(),false);assert.equal(h.opens[1].view.current(),true);
});
test('an old queued dialog close cannot cancel a newer project opening',async()=>{
  // Native dialog.close queues close on the user-interaction task source:
  // https://html.spec.whatwg.org/multipage/interactive-elements.html#close-the-dialog
  const queued=[],next=deferred(),h=harness({beforeModule:context=>{const dialog=context.$('#project-detail-modal');dialog.close=function(){if(!this.open)return;this.open=false;queued.push(()=>context.document.dispatch('close',this))}},predecessor:id=>id===2?next.promise:undefined});await h.open(1);h.context.showPage('reports');assert.equal(queued.length,1);const opening=h.context.openProject(2);await flush();queued.shift()();next.resolve();await opening;await flush();assert.equal(h.query('#detail-project-name').textContent,'Synthetic project 2');assert.equal(h.query('#project-detail-modal').open,true);assert.equal(h.all('[data-project-detail-tab="notes"]').length,1);
});
test('native close initiation invalidates a pending project before its queued close event',async()=>{
  const queued=[],next=deferred(),h=harness({beforeModule:context=>{const dialog=context.$('#project-detail-modal');dialog.close=function(){if(!this.open)return;this.open=false;queued.push(()=>context.document.dispatch('close',this))}},predecessor:id=>id===2?next.promise:undefined});await h.open(1);const opening=h.context.openProject(2);await flush();h.query('#project-detail-modal').close();next.resolve();await opening;await flush();assert.equal(h.query('#project-detail-modal').open,false,'a closed project must not reopen while the close notification is queued');assert.equal(h.query('.project-notes-pane'),null);for(const close of queued)close();
});
for(const [label,invalidate] of invalidations.filter(([label])=>!['project navigation','same-project reopen'].includes(label)))test(`pending predecessor is invalidated by ${label} before it opens a dialog`,async()=>{
  const request=deferred(),h=harness({predecessor:()=>request.promise}),opening=h.context.openProject(1);await flush();await invalidate(h);request.resolve();await opening;await flush();assert.equal(h.query('#project-detail-modal').open,false);assert.equal(h.query('.project-notes-pane'),null);assert.equal(h.calls.length,0);
});

// Extract original wrappers instead of reimplementing the new view propagation.
// Formatting anchors intentionally make additional wrappers require explicit QA.
function wrapperAfter(marker,sourceText=app){const markerIndex=sourceText.indexOf(marker);assert.ok(markerIndex>=0,'Missing source wrapper anchor '+marker);const start=sourceText.indexOf('openProject=async function',markerIndex);assert.ok(start>=0);const line=sourceText.slice(start).split('\n')[0];if(/};?\s*$/.test(line))return line;const end=sourceText.indexOf('\n}',start);assert.ok(end>=0);return sourceText.slice(start,end+2)}
const wrapperCases=[
  {name:'plans',marker:'const openProjectWithPlans=openProject;',previous:'openProjectWithPlans',beforeAwait:true},
  {name:'T&M estimate summary',marker:'const openProjectEstimateView=openProject;',previous:'openProjectEstimateView'},
  {name:'change tracking',marker:'const openProjectTmView=openProject;',previous:'openProjectTmView'},
  {name:'pricing restrictions',marker:'const openProjectForPricing=openProject;',previous:'openProjectForPricing'},
  {name:'project template',marker:'const openProjectBeforeTemplate=openProject;',previous:'openProjectBeforeTemplate'},
  {name:'tickets',marker:"$('#sub-link-result').addEventListener('click',async event=>",previous:'openProjectBeforeTickets'},
  {name:'contract value visibility',marker:'const openProjectBeforeContractValues=openProject;',previous:'openProjectBeforeContractValues'},
  {name:'reporting rate control',marker:'const pdlOpenProject=openProject;',previous:'pdlOpenProject',source:reporting}
];
for(const wrapper of wrapperCases)test(`actual ${wrapper.name} wrapper forwards the optional view and stops obsolete work`,async()=>{
  const wait=deferred(),calls=[],view={valid:true,current(){return this.valid}},sentinel=Symbol('result');let touches=0;
  const context={openProject(){},currentRole:'office',currentUser:{id:1,role:'owner'},projects:[{id:1,contractType:'tm'}],projectPlans:['new-current-plan'],projectTickets:[],company:{id:'a'},signedInCompanyId:()=> 'a',pdlContext:()=> 'identity',api:async(...args)=>{calls.push({api:args});return wait.promise},$:()=>{touches++;return null},document:{getElementById(){touches++;return null}},notify(){touches++},paintProjectTemplate(){touches++},applyContractValueVisibility(){touches++},canViewCompanyPricing(){touches++;return false}};
  context[wrapper.previous]=async(id,passedView)=>{calls.push({id,view:passedView});if(!wrapper.beforeAwait)await wait.promise;return sentinel};vm.createContext(context);vm.runInContext(wrapperAfter(wrapper.marker,wrapper.source),context);const pending=context.openProject(1,view);await flush();if(!wrapper.beforeAwait)assert.equal(calls[0].view,view);view.valid=false;wait.resolve([]);await pending;assert.equal(touches,0,'Obsolete wrapper must not inspect or modify DOM, financial state or notices');assert.deepEqual(context.projectPlans,['new-current-plan']);if(wrapper.beforeAwait)assert.equal(calls.some(call=>call.id===1),false);
});
test('actual plans wrapper passes live view to base and preserves it through success/failure',async()=>{
  for(const failed of [false,true]){const view={current:()=>true},calls=[],context={openProject(){},projectPlans:[],currentRole:'field',api:async()=>{if(failed)throw Error('synthetic');return['synthetic-plan']},openProjectWithPlans(id,passed){calls.push({id,passed});return 'base-result'}};vm.createContext(context);vm.runInContext(wrapperAfter('const openProjectWithPlans=openProject;'),context);assert.equal(await context.openProject(1,view),'base-result');assert.equal(calls[0].passed,view);assert.equal(context.projectPlans.length,failed?0:1)}
});
test('actual base renderer exits immediately for an obsolete view',()=>{
  const start=app.indexOf('function openProject(id,view){'),end=app.indexOf('\n}',start),context={};assert.ok(start>=0);vm.createContext(context);vm.runInContext(app.slice(start,end+2),context);assert.equal(context.openProject(1,{current:()=>false}),undefined);
});
for(const wrapper of wrapperCases.filter(row=>['T&M estimate summary','change tracking'].includes(row.name)))for(const failed of [false,true])test(`actual ${wrapper.name} drops delayed ${failed?'error':'success'} after its API await`,async()=>{
  const wait=deferred(),view={valid:true,current(){return this.valid}},writes=[],context={openProject(){},projects:[{id:1,contractType:'tm'}],currentRole:'office',canViewCompanyPricing:()=>true,companyTracksContractValues:()=>true,projectHealthDetails:()=>({status:'On track',reason:'Synthetic'}),escapeHtml:projectNoteEscape,$:()=>({querySelector:()=>null,insertAdjacentHTML:(position,markup)=>writes.push(markup)}),api:()=>wait.promise,notify:message=>writes.push(message)};context[wrapper.previous]=async()=>{};vm.createContext(context);vm.runInContext(wrapperAfter(wrapper.marker),context);const opening=context.openProject(1,view);await flush();const before=writes.length;view.valid=false;if(failed)wait.reject(Error('OBSOLETE WRAPPER FAILURE'));else wait.resolve(wrapper.name==='change tracking'?[]:{labor:[]});await opening;assert.equal(writes.length,before);
});
test('every project-opening layer accepts and forwards view, including reporting loaded before notes',()=>{
  const all=[...app.matchAll(/openProject=async function\(([^)]*)\)/g)];assert.equal(all.length,7,'Review/test any new app openProject layer');for(const match of all)assert.equal(match[1],'id,view');assert.match(reporting,/openProject=async function\(id,view\)/);assert.match(reporting,/await pdlOpenProject\(id,view\)/);
});

function installActualApi(context){
  const base=app.split('\n').find(line=>line.startsWith('async function api('));assert.ok(base);vm.runInContext(base,context);
  const aliases=['workspaceApi','apiBeforeSuperintendent','apiBeforeWorkspaceFeedback','apiBeforeReportLaborPreservation','apiBeforeTemplatePhotoTransaction'];
  assert.equal([...app.matchAll(/\bapi=async function\(/g)].length,aliases.length,'Review any additional API layer before shipping');
  for(const alias of aliases){const marker=`const ${alias}=api;`,start=app.indexOf(marker);assert.ok(start>=0);const assignment=app.indexOf('api=async function(',start),line=app.slice(assignment).split('\n')[0],body=/};?\s*$/.test(line)?line:app.slice(assignment,app.indexOf('\n};',assignment)+3);vm.runInContext(marker+'\n'+body,context)}
}
function apiFixture(response){
  const requests=[],updates=[],context={location:{href:'/unchanged'},signedInCompanyId:()=> 'synthetic tenant',wakeService:async()=>{},setWorkspaceUpdating:value=>updates.push(value),fetch:async(route,options)=>{requests.push({route,options});return response},reports:[],projects:[]};context.window=context;vm.createContext(context);installActualApi(context);return{context,requests,updates};
}
test('real base API plus all five wrappers preserve no-redirect notes behavior and strip custom fetch option',async()=>{
  const fixture=apiFixture({ok:false,status:401,headers:{get:()=> 'application/json'},json:async()=>({error:'Authentication required',code:'unauthenticated'})}),controller=new AbortController();await assert.rejects(fixture.context.api('/api/projects/1/notes-todos',{redirectOnUnauthorized:false,signal:controller.signal}),error=>error.message==='Authentication required'&&error.status===401&&error.code==='unauthenticated');assert.equal(fixture.context.location.href,'/unchanged');assert.equal(fixture.requests.length,1);assert.equal(fixture.requests[0].options.redirectOnUnauthorized,undefined);assert.equal(fixture.requests[0].options.signal,controller.signal);assert.equal(fixture.requests[0].options.headers['X-PDL-Company'],'synthetic tenant');assert.equal(fixture.requests[0].options.credentials,'include');assert.deepEqual(fixture.updates,[true,false]);
  await assert.rejects(fixture.context.api('/api/projects'),/Your session expired/);assert.equal(fixture.context.location.href,'/login.html?tenant=synthetic%20tenant');
});
test('real wrapped API keeps auth/me exempt and propagates structured validation status/code',async()=>{
  const unauthorized=apiFixture({ok:false,status:401,headers:{get:()=> 'application/json'},json:async()=>({error:'Authentication required'})});await assert.rejects(unauthorized.context.api('/api/auth/me'),error=>error.status===401);assert.equal(unauthorized.context.location.href,'/unchanged');
  const validation=apiFixture({ok:false,status:400,headers:{get:()=> 'application/json'},json:async()=>({error:'Control characters are not allowed',code:'invalid_text'})});await assert.rejects(validation.context.api('/api/projects/1/notes-todos',{method:'POST',body:'{}',redirectOnUnauthorized:false}),error=>error.status===400&&error.code==='invalid_text');assert.deepEqual(validation.updates,[true,false]);
});
for(const [label,invalidate] of invalidations.filter(([label])=>['tenant header','signed-in user','logout','in-app navigation','modal close'].includes(label)))test(`real wrapped API receives aborted signal if ${label} occurs while mutation awaits wakeService`,async()=>{
  const wake=deferred(),requests=[],accepted=[],h=harness({beforeModule:context=>{context.location={href:'/unchanged'};context.reports=[];context.projects=[];context.wakeService=()=>wake.promise;context.setWorkspaceUpdating=()=>{};context.fetch=async(route,options)=>{requests.push({route,options});if(options.signal?.aborted)throw options.signal.reason;accepted.push({route,options});return{ok:true,status:200,headers:{get:()=> 'application/json'},json:async()=>route.endsWith('/notes-todos')&&!options.method?{items:[]}:item({text:'MUST NOT BE ACCEPTED'})}};installActualApi(context)}});await h.open();h.click('[data-note-new="note"]');h.query('[data-notes-text]').value='Do not send after leaving';h.click('[data-notes-save]');await flush();assert.equal(requests.length,1);await invalidate(h);wake.resolve();await flush();assert.equal(requests.length,2);assert.equal(requests[1].options.signal.aborted,true);assert.equal(accepted.length,1,'A fetch implementation honoring AbortSignal cannot accept the abandoned mutation');assert.equal(h.query('.project-notes-pane'),null);
});
test('HTML loads versioned notes assets last and public-file policy exposes assets but no server/test source',()=>{
  const html=fs.readFileSync(path.join(__dirname,'index.html'),'utf8'),root=__dirname;assert.match(html,/<link rel="stylesheet" href="project-notes-ui\.css\?v=[^"]+"/);assert.match(html,/<script src="project-notes-ui\.js\?v=[^"]+"><\/script>/);assert.ok(html.indexOf('<script src="app.js')<html.indexOf('<script src="reporting-controls.js'));assert.ok(html.indexOf('<script src="reporting-controls.js')<html.indexOf('<script src="project-notes-ui.js'));assert.equal((html.match(/<script src="project-notes-ui\.js/g)||[]).length,1);for(const file of ['project-notes-ui.js','project-notes-ui.css'])assert.equal(isPublicFile(root,path.join(root,file)),true);for(const file of ['project-notes.js','project-notes-ui.test.js','server.js'])assert.equal(isPublicFile(root,path.join(root,file)),false);
});
